PRAGMA foreign_keys = ON;
CREATE TABLE user (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, emailVerified INTEGER NOT NULL DEFAULT 0, image TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE TABLE session (id TEXT PRIMARY KEY, token TEXT NOT NULL UNIQUE, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, expiresAt INTEGER NOT NULL, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, ipAddress TEXT, userAgent TEXT);
CREATE INDEX session_user ON session(userId);
CREATE TABLE account (id TEXT PRIMARY KEY, accountId TEXT NOT NULL, providerId TEXT NOT NULL, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, accessToken TEXT, refreshToken TEXT, idToken TEXT, accessTokenExpiresAt INTEGER, refreshTokenExpiresAt INTEGER, scope TEXT, password TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, UNIQUE(providerId, accountId));
CREATE INDEX account_user ON account(userId);
CREATE TABLE verification (id TEXT PRIMARY KEY, identifier TEXT NOT NULL, value TEXT NOT NULL, expiresAt INTEGER NOT NULL, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE INDEX verification_identifier ON verification(identifier);
CREATE TABLE rateLimit (id TEXT PRIMARY KEY, key TEXT NOT NULL UNIQUE, count INTEGER NOT NULL, lastRequest INTEGER NOT NULL);
CREATE TABLE profiles (owner_id TEXT PRIMARY KEY REFERENCES user(id), data TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL);
CREATE TABLE documents (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id), type TEXT NOT NULL CHECK(type IN ('registration','practising')), object_key TEXT NOT NULL UNIQUE, filename TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, licence_year INTEGER, valid_until TEXT, version INTEGER NOT NULL, uploaded_at TEXT NOT NULL);
CREATE INDEX documents_owner ON documents(owner_id, uploaded_at DESC);
CREATE TABLE applications (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id), cycle_id TEXT, institution_id TEXT, data TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, state TEXT NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','submitted')), attestation TEXT, attested_context TEXT, reference TEXT UNIQUE, snapshot TEXT, submitted_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX one_submission ON applications(owner_id, cycle_id, institution_id) WHERE state = 'submitted';
CREATE INDEX applications_owner ON applications(owner_id);
CREATE TRIGGER immutable_submission BEFORE UPDATE ON applications WHEN OLD.state = 'submitted' BEGIN SELECT RAISE(ABORT, 'Submitted applications are immutable'); END;
CREATE TRIGGER immutable_submission_delete BEFORE DELETE ON applications WHEN OLD.state = 'submitted' BEGIN SELECT RAISE(ABORT, 'Submitted applications are immutable'); END;
CREATE TABLE notifications (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id), certificate_id TEXT REFERENCES documents(id), event_key TEXT NOT NULL UNIQUE, channel TEXT NOT NULL, message TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, read_at TEXT, sent_at TEXT);
CREATE INDEX notifications_owner ON notifications(owner_id);
CREATE TABLE email_outbox (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id), event_key TEXT NOT NULL UNIQUE, recipient TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, lease_until TEXT, created_at TEXT NOT NULL, sent_at TEXT);
CREATE TABLE audit_events (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL, action TEXT NOT NULL, object_id TEXT NOT NULL, version INTEGER, created_at TEXT NOT NULL);
CREATE TRIGGER audit_profile_insert AFTER INSERT ON profiles BEGIN INSERT INTO audit_events VALUES(lower(hex(randomblob(16))), NEW.owner_id, 'profile.saved', NEW.owner_id, NEW.version, NEW.updated_at); END;
CREATE TRIGGER audit_profile_update AFTER UPDATE ON profiles BEGIN INSERT INTO audit_events VALUES(lower(hex(randomblob(16))), NEW.owner_id, 'profile.saved', NEW.owner_id, NEW.version, NEW.updated_at); END;
CREATE TRIGGER audit_document AFTER INSERT ON documents BEGIN INSERT INTO audit_events VALUES(lower(hex(randomblob(16))), NEW.owner_id, 'document.uploaded', NEW.id, NEW.version, NEW.uploaded_at); END;
CREATE TRIGGER audit_application AFTER UPDATE ON applications BEGIN INSERT INTO audit_events VALUES(lower(hex(randomblob(16))), NEW.owner_id, 'application.' || NEW.state, NEW.id, NEW.version, NEW.updated_at); END;
CREATE TRIGGER invalidate_profile AFTER UPDATE ON profiles BEGIN UPDATE applications SET attestation=NULL,attested_context=NULL,version=version+1 WHERE owner_id=NEW.owner_id AND state='draft'; END;
CREATE TRIGGER invalidate_document AFTER INSERT ON documents BEGIN
  UPDATE applications SET attestation=NULL,attested_context=NULL,version=version+1 WHERE owner_id=NEW.owner_id AND state='draft';
  UPDATE email_outbox SET status='suppressed' WHERE status IN ('pending','failed','blocked') AND event_key IN (SELECT n.event_key FROM notifications n JOIN documents d ON d.id=n.certificate_id WHERE n.channel='email' AND d.owner_id=NEW.owner_id AND d.type=NEW.type AND d.licence_year=NEW.licence_year AND d.version<NEW.version);
  UPDATE notifications SET status='suppressed' WHERE status IN ('queued','failed','blocked','saved') AND certificate_id IN (SELECT id FROM documents WHERE owner_id=NEW.owner_id AND type=NEW.type AND licence_year=NEW.licence_year AND version<NEW.version);
END;
CREATE TRIGGER invalidate_email AFTER UPDATE OF email ON user WHEN OLD.email<>NEW.email BEGIN UPDATE applications SET attestation=NULL,attested_context=NULL,version=version+1 WHERE owner_id=NEW.id AND state='draft'; END;
